const STORAGE_KEY = 'zo-packeta-bozp-protocol-v1';
const RECORDS_KEY = 'zo-packeta-bozp-records-v1';
const LETTERHEAD_LOGO = 'data:image/png;base64,';
const defaultFindings = [
  ['7','urgent','Káble vedené po stene','Káble sú po stavebných úpravách vedené po stene. Doplňte čas zistenia, zdroj informácie a označenie fotodokumentácie.','NV SR č. 391/2006 Z. z.; vyhláška č. 508/2009 Z. z.','Zabezpečiť káble uložením do lišty alebo kanála alebo ich odstránením tak, aby nehrozilo poškodenie, potknutie ani úraz elektrickým prúdom. Doložiť fotodokumentáciu po náprave.','do 3 pracovných dní od doručenia protokolu'],
  ['11','urgent','Skladovanie batérií a nebezpečných látok','Doplňte umiestnenie, označenie, stav skladovania a dôkaz.','zákon č. 124/2006 Z. z.; nariadenie (ES) č. 1272/2008','Označiť a oddeliť batérie od ostatných vecí podľa bezpečnostného listu alebo návodu výrobcu, alebo preukázať, že súčasné uloženie týmto požiadavkám zodpovedá.','do 3 pracovných dní od doručenia protokolu'],
  ['12','urgent','Neoznačená nádoba s neznámym obsahom','Doplňte opis nádoby, obsah, zápach, miesto a vyjadrenie prítomnej osoby.','nariadenie (ES) č. 1272/2008; zákon č. 79/2015 Z. z. o odpadoch','Nádobu bezodkladne označiť, zabezpečiť proti úniku a doložiť evidenciu a dokumentáciu o likvidácii.','označenie do 3 pracovných dní; doklady do 7 pracovných dní od doručenia'],
  ['14','urgent','Prívod elektriny cez predlžovacie káble','Doplňte rozsah, počet káblov, pripojené zariadenia a fotodokumentáciu.','vyhláška č. 508/2009 Z. z.; NV SR č. 391/2006 Z. z.','Odstrániť reťazenie predlžovacích káblov a zabezpečiť pevný prívod zodpovedajúci príkonu zariadení. Doložiť revíznu správu.','odstránenie do 3 pracovných dní; revízna správa do 7 pracovných dní'],
  ['15','urgent','Protipožiarne dvere a voľný únik','Doplňte konkrétny nedostatok a označenie dôkazu.','NV SR č. 391/2006 Z. z.; zákon č. 314/2001 Z. z.','Odstrániť nedostatok, zabezpečiť funkčnosť dverí a voľný únik. Doložiť doklad o kontrole.','do 3 pracovných dní od doručenia protokolu'],
  ['16','urgent','Nezabezpečená tlaková nádoba','Doplňte umiestnenie, stav a označenie fotodokumentácie.','vyhláška č. 508/2009 Z. z.','Bezodkladne zabezpečiť nádobu proti pádu a poškodeniu. Doložiť doklady o odborných prehliadkach a skúškach.','zabezpečenie do 3 pracovných dní; doklady do 7 pracovných dní'],
  ['2, 3','process','Manipulácia s bremenami a hmotnostné limity','Doplňte opis procesu, hmotnosti bremien, vyjadrenia prítomných osôb a súčasný stav evidencie.','NV SR č. 281/2006 Z. z., § 3 a § 4','Zaviesť a písomne zdokumentovať proces zisťovania hmotnosti manipulovaných bremien, kontroly limitov na osobu a za zmenu, posúdenia rizika a informovania zamestnancov.','do 14 dní od doručenia protokolu'],
  ['9','process','Nosnosť regálov a hmotnosť paliet','Doplňte limit regálu, hmotnosť paliet a označenie fotodokumentácie.','zákon č. 124/2006 Z. z.','Zistiť a označiť hmotnosť paliet, zabezpečiť dodržiavanie nosnosti regálov a doložiť pravidlá užívania a kontroly regálových systémov.','do 14 dní od doručenia protokolu'],
  ['13','process','Postup pri náleze nebezpečnej látky','Doplňte, aké pokyny boli zamestnancom dostupné a kto podal vyjadrenie.','zákon č. 124/2006 Z. z.','Vypracovať a sprístupniť pracovnú inštrukciu a poučiť zamestnancov o postupe pri náleze nebezpečnej látky.','do 14 dní od doručenia protokolu'],
  ['19','process','Zodpovednosti a eskalačný postup','Doplňte zistený stav a vyjadrenia k zodpovednostiam.','zákon č. 124/2006 Z. z.','Písomne určiť zodpovednosť za BOZP na pracovisku a eskalačný postup pri riziku alebo úraze. Doložiť platný organigram.','do 14 dní od doručenia protokolu'],
  ['1','documents','Meranie teploty na pracovisku','Doplňte, aký doklad bol vyžiadaný a či bol predložený.','NV SR č. 391/2006 Z. z.','Doložiť protokoly o meraní teploty a ich vyhodnotenie.','doklady do 7 pracovných dní od doručenia protokolu'],
  ['4','documents','Školenia BOZP','Doplňte tvrdený obsah školenia a stav predloženia dokladov.','zákon č. 124/2006 Z. z.','Doložiť záznamy o školeniach vrátane dátumov, obsahu a prezenčných listín.','doklady do 7 pracovných dní od doručenia protokolu'],
  ['5, 17','documents','Pracovný poriadok a pracovné inštrukcie','Doplňte dostupnosť dokumentov a či boli poskytnuté na nahliadnutie alebo v kópii.','zákon č. 124/2006 Z. z.','Zaslať kópie pracovného poriadku a pracovných inštrukcií a doložiť prístup zamestnancov k intranetu.','do 7 pracovných dní od doručenia protokolu'],
  ['6','documents','Posúdenie rizík a kategorizácia prác','Doplňte kedy bolo posúdenie vyžiadané a či bolo predložené.','zákon č. 124/2006 Z. z.; zákon č. 355/2007 Z. z.','Doložiť platné posúdenie rizík a kategorizáciu prác vrátane aktualizácie po zmenách pracoviska.','doklady do 7 pracovných dní od doručenia protokolu'],
  ['8','documents','Osvetlenie pracoviska','Doplňte, ktorej časti pracoviska sa týka.','NV SR č. 391/2006 Z. z.','Doložiť protokol o meraní osvetlenia a vyhodnotenie splnenia požiadaviek.','do 7 pracovných dní od doručenia protokolu'],
  ['10','documents','Stabilné hasiace zariadenie a protipožiarna ochrana','Doplňte zistenie, vyjadrenie prítomnej osoby a dôkaz.','NV SR č. 391/2006 Z. z.; zákon č. 314/2001 Z. z.','Doložiť dokumentáciu o kontrolách a revíziách zariadenia a o skladovaní horľavých materiálov.','doklady do 7 pracovných dní od doručenia protokolu'],
  ['18','documents','Evidencia pracovných úrazov','Doplňte obdobie, za ktoré bola evidencia vyžiadaná.','Zákonník práce','Doložiť evidenciu pracovných úrazov v anonymizovanej forme.','do 7 pracovných dní od doručenia protokolu'],
  ['20','documents','Bezpečné parkovanie v areáli','Doplňte miesto, vozidlo len ak je potrebné, a označenie dôkazu.','zákon č. 124/2006 Z. z.','Prijať opatrenie na zabezpečenie bezpečných trás pre peších a poučiť dotknuté osoby.','do 7 pracovných dní od doručenia protokolu']
];
const blankState = () => ({
  meta:{ protocolDate:new Date().toISOString().slice(0,10), controlDate:'', timeFrom:'', timeTo:'', workplace:'', workplaceAddress:'', noticeDate:'', unionName:'Základná odborová organizácia pri Packeta Slovakia s. r. o.', unionAddress:'Strážska cesta 10406/28, 960 01 Zvolen', unionIco:'57 888 353', inspector:'', employer:'Packeta Slovakia s. r. o.', employerIco:'48 136 999', employerAddress:'Vajnorská 100/B, 831 04 Bratislava', employerPresent:'', reportDate:'', placeOfSigning:'Zvolen', workStop:'no', workStopText:''},
  findings: []
});
let state;
let activeRecordId = null;
try { state = JSON.parse(localStorage.getItem(STORAGE_KEY)) || blankState(); } catch { state = blankState(); }
const editor = document.querySelector('#editor');
const nav = document.querySelector('#sectionNav');
const esc = (s='') => String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const field = (label,key,type='text',placeholder='') => `<label>${label}<input type="${type}" data-meta="${key}" value="${esc(state.meta[key]||'')}" placeholder="${placeholder}"></label>`;
const textField=(label,key,placeholder='')=>`<label>${label}<textarea rows="3" data-meta="${key}" placeholder="${placeholder}">${esc(state.meta[key]||'')}</textarea></label>`;
function render(){
  editor.innerHTML=`
  <section class="step" id="basic"><div class="section-head"><div><h2>1. Údaje o kontrole</h2><p>Vyplňte overiteľné údaje z kontroly a prítomné osoby.</p></div></div>
  <div class="three-columns">${field('Dátum kontroly','controlDate','date')}${field('Od','timeFrom','time','')}${field('Do','timeTo','time','')}</div>
  ${field('Miesto kontroly','workplace','text','napr. Depo Packeta Žilina')}${field('Adresa miesta','workplaceAddress','text','')}${field('Dátum oznámenia kontroly','noticeDate','date')}
  ${textField('Kontrolu vykonal/a','inspector','Meno, funkcia v odborovom orgáne')}${textField('Prítomní za zamestnávateľa','employerPresent','Mená, funkcie a prípadné vyjadrenia o oprávnení konať')}
  </section>
  <section class="step" id="parties"><div class="section-head"><div><h2>2. Údaje zmluvných strán</h2><p>Údaje sa prenesú do hlavičky protokolu.</p></div></div>
  ${field('Odborová organizácia','unionName')}${field('Sídlo odborovej organizácie','unionAddress')}${field('IČO odborovej organizácie','unionIco')}
  ${field('Zamestnávateľ','employer')}${field('IČO zamestnávateľa','employerIco')}${field('Sídlo zamestnávateľa','employerAddress')}
  </section>
  <section class="step" id="findings"><div class="section-head"><div><h2>3. Zistenia a požiadavky</h2><p>Každý bod musí oddeliť skutkové zistenie, právny základ, požadované opatrenie a lehotu.</p></div><button class="secondary add-finding" id="addFinding">Pridať bod</button></div><div class="notice">Nový protokol je prázdny. Každé zistenie pridajte tlačidlom „Pridať bod“ a vyplňte ho podľa konkrétnej kontroly.</div><div id="findingsList"></div></section>
  <section class="step" id="closing"><div class="section-head"><div><h2>4. Záver a podpis</h2><p>Vyberte, či odborový orgán požaduje prerušenie práce.</p></div></div>
  <div class="radio-group"><label><input type="radio" name="workStop" value="no" ${state.meta.workStop==='no'?'checked':''}> Prerušenie práce sa nepožaduje</label><label><input type="radio" name="workStop" value="yes" ${state.meta.workStop==='yes'?'checked':''}> Požaduje sa prerušenie práce</label></div>
  ${textField('Odôvodnenie prerušenia práce, ak sa požaduje','workStopText','')}
  <div class="three-columns">${field('Miesto podpisu','placeOfSigning')}${field('Dátum vyhotovenia','reportDate','date')}${field('Označenie protokolu','protocolDate','date')}</div>
  <div class="footer-actions"><button class="secondary" id="saveDraftBottom">Uložiť zápis</button><button class="primary" id="printPdfBottom">Stiahnuť PDF</button></div></section>`;
  renderFindings(); renderNav(); renderRecords(); bindMeta();
}
function renderNav(){nav.innerHTML=['Údaje o kontrole','Zmluvné strany','Zistenia a požiadavky','Záver a podpis'].map((x,i)=>`<button data-target="${['basic','parties','findings','closing'][i]}">${i+1}. ${x}</button>`).join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.target).scrollIntoView({behavior:'smooth'}));}
function renderFindings(){ const list=document.querySelector('#findingsList'); const t=document.querySelector('#findingTemplate'); list.innerHTML=''; state.findings.forEach((finding,index)=>{const node=t.content.cloneNode(true);const card=node.querySelector('.finding-card');card.dataset.id=finding.id;node.querySelector('.finding-number').textContent=`Bod ${finding.point||index+1}`;node.querySelectorAll('[data-field]').forEach(el=>{const k=el.dataset.field;if(k==='photos')return;el.value=finding[k]||'';el.oninput=()=>{finding[k]=el.value;node.querySelector('.finding-number').textContent=`Bod ${finding.point||index+1}`;};});node.querySelector('.remove').onclick=()=>{state.findings=state.findings.filter(x=>x.id!==finding.id);renderFindings();};const photoInput=node.querySelector('[data-field="photos"]');photoInput.onchange=async()=>{for(const f of photoInput.files){finding.photos.push(await fileToDataUrl(f));}renderFindings();};const photoList=node.querySelector('.photo-list');finding.photos.forEach((p,i)=>{const wrap=document.createElement('div');wrap.innerHTML=`<img src="${p.data}" alt="Fotografia k bodu ${esc(finding.point)}"><button class="remove-photo" type="button">Odstrániť</button>`;wrap.querySelector('button').onclick=()=>{finding.photos.splice(i,1);renderFindings();};photoList.append(wrap);});list.append(node);}); document.querySelector('#addFinding').onclick=()=>{state.findings.push({id:crypto.randomUUID(),point:'',category:'urgent',title:'',finding:'',legalBasis:'',request:'',deadline:'',evidence:'',employerResponse:'',photos:[]});renderFindings();};}
function bindMeta(){editor.querySelectorAll('[data-meta]').forEach(el=>el.oninput=()=>state.meta[el.dataset.meta]=el.value);editor.querySelectorAll('[name="workStop"]').forEach(el=>el.onchange=()=>state.meta.workStop=el.value);document.querySelector('#saveDraftBottom').onclick=saveRecord;document.querySelector('#printPdfBottom').onclick=printPdf;}
function fileToDataUrl(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({name:file.name,data:r.result});r.onerror=reject;r.readAsDataURL(file);});}
function saveDraft(showMessage=false){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));if(showMessage)alert('Rozpracovaný protokol je uložený v tomto prehliadači.');}catch{alert('Prehliadač nemá dostatok miesta na uloženie. Skúste zmenšiť alebo odstrániť fotografie a zápis vyexportovať.');}}
function getRecords(){try{return JSON.parse(localStorage.getItem(RECORDS_KEY))||[];}catch{return [];}}
function recordTitle(){return state.meta.workplace ? `Kontrola - ${state.meta.workplace}` : 'Nový BOZP zápis';}
function saveRecord(){try{const records=getRecords();const id=activeRecordId||crypto.randomUUID();const record={id,title:recordTitle(),savedAt:new Date().toISOString(),state:JSON.parse(JSON.stringify(state))};const index=records.findIndex(r=>r.id===id);if(index>=0)records[index]=record;else records.unshift(record);localStorage.setItem(RECORDS_KEY,JSON.stringify(records));activeRecordId=id;saveDraft(false);renderRecords();alert('Zápis je uložený v tomto prehliadači.');}catch{alert('Prehliadač nemá dostatok miesta na uloženie. Skúste zmenšiť alebo odstrániť fotografie a zápis vyexportovať.');}}
function renderRecords(){const root=document.querySelector('#recordsList');if(!root)return;const records=getRecords();if(!records.length){root.innerHTML='<p class="empty-records">Zatiaľ nemáte uložený žiadny zápis.</p>';return;}root.innerHTML=records.map(r=>`<div class="record-row"><button class="record-open" data-open="${r.id}">${esc(r.title)}<span class="record-date">${new Date(r.savedAt).toLocaleDateString('sk-SK')}</span></button><button class="record-delete" data-delete="${r.id}">Vymazať</button></div>`).join('');root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const record=getRecords().find(r=>r.id===b.dataset.open);if(record){state=record.state;activeRecordId=record.id;render();window.scrollTo({top:0,behavior:'smooth'});}});root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Vymazať tento uložený zápis?')){const remaining=getRecords().filter(r=>r.id!==b.dataset.delete);localStorage.setItem(RECORDS_KEY,JSON.stringify(remaining));if(activeRecordId===b.dataset.delete)activeRecordId=null;renderRecords();}});}
function exportJson(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});download(blob,`BOZP_protokol_${state.meta.controlDate||'rozpracovane'}.json`);}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href);}
function categoryTitle(k){return {urgent:'A. Nedostatky vyžadujúce bezodkladné opatrenia',process:'B. Nedostatky v pracovných postupoch a organizácii',documents:'C. Nepreukázané plnenie povinností - doklady a posúdenia'}[k];}
function formattedDate(v){if(!v)return '________________';const [y,m,d]=v.split('-');return `${d}. ${m}. ${y}`;}
function printPdf(){saveDraft(false); const m=state.meta; const byCat=['urgent','process','documents'];const sections=byCat.map(cat=>{const items=state.findings.filter(f=>f.category===cat);if(!items.length)return '';return `<h2>${categoryTitle(cat)}</h2>${items.map(f=>`<article class="finding"><h3>Bod ${esc(f.point)} - ${esc(f.title)}</h3><p><b>Zistenie:</b> ${esc(f.finding).replace(/\n/g,'<br>')}</p><p><b>Právny základ:</b> ${esc(f.legalBasis)}</p><p><b>Požiadavka odborového orgánu:</b> ${esc(f.request).replace(/\n/g,'<br>')}</p><p><b>Lehota:</b> ${esc(f.deadline)}</p>${f.evidence?`<p><b>Dôkaz:</b> ${esc(f.evidence)}</p>`:''}<div class="response"><b>Vyjadrenie zamestnávateľa (opatrenie, termín, zodpovedná osoba):</b><br>${esc(f.employerResponse||'').replace(/\n/g,'<br>')||'<span class="blank">&nbsp;</span>'}</div></article>`).join('')}`}).join(''); const photos=state.findings.filter(f=>f.photos?.length).map(f=>`<section class="photo-section"><h3>Fotodokumentácia - bod ${esc(f.point)}: ${esc(f.title)}</h3><div class="photos">${f.photos.map(p=>`<figure><img src="${p.data}"><figcaption>${esc(p.name)}</figcaption></figure>`).join('')}</div></section>`).join('');const stop=m.workStop==='yes'?`Odborový orgán požaduje prerušenie práce podľa § 149 ods. 1 písm. c) Zákonníka práce z týchto dôvodov: ${esc(m.workStopText)}`:'Odborový orgán v tomto protokole nepožaduje prerušenie práce podľa § 149 ods. 1 písm. c) Zákonníka práce.'; const doc=`<!doctype html><html lang="sk"><head><base href="${location.href.slice(0, location.href.lastIndexOf('/')+1)}"><meta charset="utf-8"><title>Protokol BOZP ${esc(m.workplace)}</title><style>@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;padding:20mm 20mm 35mm;font-family:Georgia,'Times New Roman',serif;color:#17222b;font-size:10pt;line-height:1.42}.letterhead{height:40mm}.logo{width:62mm;height:auto;display:block}.org{margin-top:4mm;color:#2e6f95;font-size:10pt}.document-content{padding-top:5mm}.title{text-align:center;margin:0 0 18px;font-family:Arial,sans-serif}.title h1{font-size:17pt;margin:0;color:#123b5d}.title p{margin:4px 0}.meta{margin:8px 0}.meta b{color:#123b5d}h2{font-family:Arial,sans-serif;font-size:13pt;color:#123b5d;border-bottom:1px solid #b8cbd6;padding-bottom:4px;margin-top:22px;break-after:avoid}h3{font-family:Arial,sans-serif;font-size:11pt;margin:17px 0 7px;color:#123b5d}p{margin:5px 0}.finding{page-break-inside:avoid;border-bottom:1px solid #d9e2e8;padding:0 0 12px;margin-bottom:12px}.response{margin-top:9px;padding:8px;background:#f4f8fa;min-height:48px;font-family:Arial,sans-serif}.blank{display:block;min-height:34px}.signature{margin-top:28px;page-break-inside:avoid}.sig-line{margin-top:52px;border-top:1px solid #17222b;width:260px;padding-top:5px}.photo-section{page-break-before:always}.photos{display:grid;grid-template-columns:1fr 1fr;gap:14px}.photos figure{margin:0;page-break-inside:avoid}.photos img{width:100%;max-height:110mm;object-fit:contain;border:1px solid #d9e2e8}.photos figcaption{font-size:8pt;color:#526a77;font-family:Arial,sans-serif}footer{position:fixed;left:20mm;right:20mm;bottom:14mm;border-top:1px solid #c8dce8;padding-top:4mm;color:#123b5d;font-size:7.8pt;line-height:1.25}@media print{.print{display:none}}</style></head><body><header class="letterhead"><div><img class="logo" src="${LETTERHEAD_LOGO}"><div class="org">Základná odborová organizácia pri Packeta Slovakia s.r.o</div></div></header><main class="document-content"><div class="title"><h1>PROTOKOL</h1><p>o kontrole stavu bezpečnosti a ochrany zdravia pri práci podľa § 149 Zákonníka práce</p><p><b>${esc(m.workplace||'Pracovisko')}</b> - kontrola zo dňa ${formattedDate(m.controlDate)}</p></div><h2>I. Odborový orgán, ktorý kontrolu vykonal</h2><p><b>Odborový orgán:</b> ${esc(m.unionName)}, ${esc(m.unionAddress)}, IČO ${esc(m.unionIco)}.</p><p><b>Kontrolu vykonal/a:</b> ${esc(m.inspector)}</p><p><b>Kontrolovaný zamestnávateľ:</b> ${esc(m.employer)}, IČO ${esc(m.employerIco)}, ${esc(m.employerAddress)}.</p><h2>II. Dátum, čas a miesto kontroly</h2><p><b>Dátum a čas:</b> ${formattedDate(m.controlDate)}, od ${esc(m.timeFrom||'____')} do ${esc(m.timeTo||'____')} hod.</p><p><b>Miesto:</b> ${esc(m.workplace)}, ${esc(m.workplaceAddress)}</p><p><b>Prítomní za zamestnávateľa:</b> ${esc(m.employerPresent)}</p><p><b>Oznámenie kontroly:</b> Kontrola bola zamestnávateľovi oznámená ${formattedDate(m.noticeDate)}.</p><h2>III. Nedostatky zistené kontrolou, ktorých odstránenie odborový orgán požaduje</h2><p>Odborový orgán požaduje podľa § 149 ods. 1 písm. c) Zákonníka práce odstránenie nižšie uvedených nedostatkov. Lehoty sú určené podľa závažnosti rizika.</p>${sections}<h2>IV. Prerušenie práce</h2><p>${stop}</p><h2>V. Vyjadrenie zamestnávateľa</h2><p>Zamestnávateľ sa vyjadrí písomne ku každému bodu, najmä či zistenie uznáva, aké opatrenie vykoná, do kedy a kto zaň zodpovedá.</p><div class="signature"><p>V ${esc(m.placeOfSigning||'________________')}, dňa ${formattedDate(m.reportDate)}</p><div class="sig-line">${esc(m.inspector)}<br>za odborový orgán</div></div>${photos?`<section class="photo-section"><h2>Príloha - Fotodokumentácia</h2>${photos}</section>`:''}</main><footer>Základná odborová organizácia pri Packeta Slovakia s.r.o&nbsp;&nbsp;|&nbsp;&nbsp;IČO: 57 888 353<br>Sídlo: Strážska cesta 10406/28, 960 01, Zvolen<br>E-mail: info@odborypacketa.eu&nbsp;&nbsp;|&nbsp;&nbsp;Telefón: +421 903 029 737&nbsp;&nbsp;|&nbsp;&nbsp;Web: www.odborypacketa.eu</footer><script>window.onload=()=>window.print()<\/script></body></html>`;const win=window.open('','_blank');win.document.write(doc);win.document.close();}
document.querySelector('#brandLogo').src=LETTERHEAD_LOGO;document.querySelector('#saveDraft').onclick=saveRecord;document.querySelector('#printPdf').onclick=printPdf;document.querySelector('#exportJson').onclick=exportJson;document.querySelector('#newProtocol').onclick=()=>{if(confirm('Vytvoriť nový prázdny protokol? Neuložené zmeny sa stratia.')){localStorage.removeItem(STORAGE_KEY);state=blankState();activeRecordId=null;render();}};document.querySelector('#importJson').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{state=JSON.parse(r.result);activeRecordId=null;render();}catch{alert('Súbor sa nepodarilo načítať.')}};r.readAsText(f)};render();
